#import "PluginResourceDetailViewController.h"
#import "HostTheme.h"
#import "HostToolbar.h"
#import "PyHost.h"
#import "ServiceStore.h"
#import "M3UParser.h"

@interface PluginResourceDetailViewController () <UITableViewDataSource,UITableViewDelegate,NSURLSessionDataDelegate,NSURLSessionTaskDelegate>
@property(nonatomic,strong) UILabel *notice;
@property(nonatomic) BOOL operationPending;
@property(nonatomic,copy) NSString *probeStatus;
@property(nonatomic,strong) NSURLSession *probeSession;
@property(nonatomic,strong) NSURLSessionDataTask *probeTask;
@property(nonatomic,strong) NSMutableData *probeData;
@property(nonatomic) NSUInteger probeGeneration;
@property(nonatomic) NSInteger probeStatusCode;
@property(nonatomic,strong) NSURL *probeResponseURL;
@property(nonatomic) NSInteger probeChannelCount;
@property(nonatomic) BOOL probingPlaylist;
@property(nonatomic) BOOL probePlaylistChecked;
- (NSString *)baseURL;
- (void)showNotice:(NSString *)message;
- (void)showError:(NSString *)message;
@end

@implementation PluginResourceDetailViewController
- (instancetype)init {return [super initWithStyle:UITableViewStyleInsetGrouped];}
- (BOOL)mediaCapable {return [ServiceStore isVODMediaService:self.service];}
- (BOOL)liveCapable {NSArray *caps=[self.service[@"capabilities"] isKindOfClass:NSArray.class]?self.service[@"capabilities"]:@[];return [self.service[@"playlistPath"] length]>0||[caps containsObject:@"live"]||[self.service[@"protocol"] isEqual:@"python-http"];}
- (BOOL)running {return [PyHost isRunningServiceIdentifier:self.service[@"id"]];}
- (NSString *)baseURL {NSInteger port=[self.service[@"port"] integerValue];return [NSString stringWithFormat:@"http://127.0.0.1:%ld",(long)port];}
- (void)viewDidLoad {
    [super viewDidLoad];self.title=self.service[@"name"]?:@"资源详情";self.tableView.backgroundColor=HostBackground();self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=58;
    self.notice=[UILabel new];self.notice.textColor=UIColor.secondaryLabelColor;self.notice.numberOfLines=0;self.notice.textAlignment=NSTextAlignmentCenter;self.tableView.backgroundView=self.notice;
    __weak typeof(self) w=self;self.navigationItem.rightBarButtonItems=@[HostToolbar(@[@{@"icon":@"square.and.pencil",@"title":@"编辑配置",@"action":[UIAction actionWithHandler:^(UIAction *a){if(w.onEdit)w.onEdit(w.service);}]}])];
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(stateChanged) name:PyHostRuntimeStateDidChangeNotification object:nil];
}
- (void)viewWillAppear:(BOOL)animated {[super viewWillAppear:animated];for(NSDictionary *latest in [ServiceStore services])if([latest[@"id"] isEqual:self.service[@"id"]]){self.service=latest;break;}self.title=self.service[@"name"];[self.tableView reloadData];}
- (void)viewDidDisappear:(BOOL)animated {[super viewDidDisappear:animated];self.probeGeneration++;[self.probeTask cancel];self.probeTask=nil;[self.probeSession invalidateAndCancel];self.probeSession=nil;}
- (void)dealloc {[NSNotificationCenter.defaultCenter removeObserver:self];[self.probeTask cancel];[self.probeSession invalidateAndCancel];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task willPerformHTTPRedirection:(NSHTTPURLResponse *)response newRequest:(NSURLRequest *)request completionHandler:(void (^)(NSURLRequest * _Nullable))completionHandler {completionHandler(nil);}
- (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)task didReceiveResponse:(NSURLResponse *)response completionHandler:(void (^)(NSURLSessionResponseDisposition))completion {BOOL valid=task==self.probeTask&&[response isKindOfClass:NSHTTPURLResponse.class]&&response.expectedContentLength<=1024*1024;self.probeStatusCode=[response isKindOfClass:NSHTTPURLResponse.class]?((NSHTTPURLResponse *)response).statusCode:0;self.probeResponseURL=response.URL;completion(valid?NSURLSessionResponseAllow:NSURLSessionResponseCancel);}
- (void)URLSession:(NSURLSession *)session dataTask:(NSURLSessionDataTask *)task didReceiveData:(NSData *)data {if(task!=self.probeTask)return;if(self.probeData.length+data.length>1024*1024){[task cancel];return;}[self.probeData appendData:data];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task didCompleteWithError:(NSError *)error {if(task!=self.probeTask)return;NSUInteger generation=self.probeGeneration;NSData *data=[self.probeData copy];NSInteger status=self.probeStatusCode;NSURL *url=self.probeResponseURL;dispatch_async(dispatch_get_main_queue(),^{if(generation!=self.probeGeneration)return;self.probeTask=nil;[self.probeSession finishTasksAndInvalidate];self.probeSession=nil;if(error){self.probeStatus=[NSString stringWithFormat:@"检测失败 · %@",error.code==NSURLErrorCancelled?@"响应超过 1 MiB 或请求已取消":(error.localizedDescription?:@"网络错误")];}else if(status<200||status>=300){self.probeStatus=[NSString stringWithFormat:@"HTTP %ld · 接口未通过",(long)status];}else if(self.probingPlaylist){NSString *text=[[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];NSArray *channels=text?[M3UParser parse:text baseURL:url]:@[];BOOL playlistFormat=[text containsString:@"#EXTM3U"]||[text containsString:@"#EXTINF"]||channels.count>0;if(playlistFormat){self.probePlaylistChecked=YES;self.probeChannelCount=channels.count;self.probeStatus=[NSString stringWithFormat:@"HTTP %ld · 播放列表可读 · %lu 个频道",(long)status,(unsigned long)channels.count];}else{self.probePlaylistChecked=NO;self.probeStatus=[NSString stringWithFormat:@"HTTP %ld · 响应可读，但未识别为频道列表",(long)status];}}else{ id json=data.length<=256*1024?[NSJSONSerialization JSONObjectWithData:data options:0 error:NULL]:nil;NSArray *caps=[json isKindOfClass:NSDictionary.class]&&[json[@"data"] isKindOfClass:NSDictionary.class]?json[@"data"][@"capabilities"]:nil;self.probeStatus=[NSString stringWithFormat:@"HTTP %ld · %@",(long)status,[caps isKindOfClass:NSArray.class]?[NSString stringWithFormat:@"能力 %@",[caps componentsJoinedByString:@"、"]]:@"接口响应可读"];}[self.tableView reloadSections:[NSIndexSet indexSetWithIndexesInRange:NSMakeRange(1,2)] withRowAnimation:UITableViewRowAnimationNone];});}
- (void)stateChanged {[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView {return 4;}
- (NSArray *)resourceRows {
    NSArray *caps=[self.service[@"capabilities"] isKindOfClass:NSArray.class]?self.service[@"capabilities"]:@[];
    NSMutableArray *rows=[NSMutableArray arrayWithArray:@[@{@"title":@"运行能力",@"value":[NSString stringWithFormat:@"%@ · %@",self.service[@"engine"]?:@"未知引擎",self.service[@"protocol"]?:@"未知协议"]},@{@"title":@"能力探测",@"value":caps.count?[caps componentsJoinedByString:@"、"]:@"启动后验证实际能力"}]];
    if(self.mediaCapable)[rows addObject:@{@"title":@"打开影视",@"value":@"资源 → 站点 → 详情选集 → 播放"}];
    if(self.liveCapable)[rows addObject:@{@"title":@"打开直播频道",@"value":@"读取本机播放列表后加入频道页"}];
    if([self.service[@"protocol"] isEqual:@"catpaw-http"]){[rows addObject:@{@"title":@"源配置与账号",@"value":@"管理此源的站点、网盘与登录信息",@"action":@"configuration"}];
        NSDictionary *states=@{@"verified":@"已下载并通过 MD5 校验",@"downloaded_without_checksum":@"已下载 · 来源未提供配置校验",@"missing_using_defaults":@"未提供配套配置 · 启动时使用脚本默认值"};
        [rows addObject:@{@"title":@"配套配置",@"value":states[self.service[@"configurationState"]?:@""]?:([self.service[@"manifest"][@"configEntry"] length]?@"包内配置":@"未知 · 可检查更新补齐")}];}
    NSArray *verifiedLocalChecksums=[self.service[@"manifest"][@"verifiedLocalChecksums"] isKindOfClass:NSArray.class]?self.service[@"manifest"][@"verifiedLocalChecksums"]:@[];
    if([self.service[@"url"] length]){NSString *status=[self.service[@"downloadChecksum"] length]?@"下载时 MD5 校验已通过（不代表内容已播放）":@"未提供文件校验";if(verifiedLocalChecksums.count)status=[status stringByAppendingFormat:@"；ZIP 内 %@ 已校验",[verifiedLocalChecksums componentsJoinedByString:@"、"]];[rows addObject:@{@"title":@"文件校验",@"value":status}];[rows addObject:@{@"title":@"资源来源",@"value":self.service[@"url"],@"action":@"copySource"}];}
    else if(verifiedLocalChecksums.count)[rows addObject:@{@"title":@"文件校验",@"value":[NSString stringWithFormat:@"ZIP 内 MD5 已通过：%@",[verifiedLocalChecksums componentsJoinedByString:@"、"]]}];
    return rows;
}
- (NSArray *)managementRows {
    if([self.service[@"builtin"] boolValue])return @[];
    NSMutableArray *rows=[NSMutableArray arrayWithObject:@{@"title":@"查看此资源日志",@"value":@"独立日志 · 查看与导出",@"action":@"log"}];
    if([self.service[@"url"] length])[rows addObject:@{@"title":@"检查资源更新",@"value":@"校验新版 · 保留服务 ID、账号和配置",@"action":@"update"}];
    if([self.service[@"previousImport"] isKindOfClass:NSDictionary.class])[rows addObject:@{@"title":@"切回上一版代码",@"value":@"保留账号数据与当前端口",@"action":@"rollback"}];
    [rows addObject:@{@"title":@"移除资源",@"value":@"移除本机代码及配置",@"action":@"remove"}];return rows;
}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section {if(section==0)return self.resourceRows.count;if(section==1)return 4;if(section==2)return 3;return self.managementRows.count;}
- (NSString *)tableView:(UITableView *)tableView titleForHeaderInSection:(NSInteger)section {return @[@"资源能力",@"运行状态",@"本机接口",@"管理与诊断"][section];}
- (NSString *)tableView:(UITableView *)tableView titleForFooterInSection:(NSInteger)section {if(section==0)return @"点击“使用”后才会按需启动服务。运行中、接口健康、列表可读和视频解码是不同状态。";if(section==1)return [self.service[@"manifest"][@"compatibilityNote"] isKindOfClass:NSString.class]?self.service[@"manifest"][@"compatibilityNote"]:@"服务可独立启停；停止失败时请查看此资源的日志。";return nil;}
- (NSDictionary *)rowAt:(NSIndexPath *)ip {
    if(ip.section==0)return self.resourceRows[ip.row];
    NSString *port=[NSString stringWithFormat:@"%@",self.service[@"port"]?:@"未知"];
    if(ip.section==1){NSArray *rows=@[@{@"title":@"服务进程",@"value":self.operationPending?@"正在启停…":(self.running?@"运行中 · 视频解码状态未知":@"已停止")},@{@"title":self.running?@"停止服务":@"启动服务",@"value":self.running?@"仅停止此服务":@"按需启动此服务",@"action":@"toggle"},@{@"title":@"检测资源接口",@"value":self.probeStatus?:@"点击检测声明的本机接口",@"action":@"probe"},@{@"title":@"运行状态说明",@"value":self.service[@"status"]?:@"暂无状态信息"}];return rows[ip.row];}
    if(ip.section==2){NSString *playlist=[self.service[@"playlistPath"] length]?self.service[@"playlistPath"]:@"未声明 · 编辑服务填写";NSString *count=self.probePlaylistChecked?[NSString stringWithFormat:@"%ld · 最近一次接口检测",(long)self.probeChannelCount]:@"未知 · 尚未识别出有效列表";return @[@{@"title":@"复制本机地址",@"value":[NSString stringWithFormat:@"http://127.0.0.1:%@",port],@"action":@"copy"},@{@"title":@"播放列表路径",@"value":playlist},@{@"title":@"频道数量",@"value":count}][ip.row];}
    return self.managementRows[ip.row];
}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)ip {NSDictionary *row=[self rowAt:ip];BOOL sourceURL=[row[@"action"] isEqual:@"copySource"];NSString *reuse=sourceURL?@"service.resource.source":@"service.resource.value";UITableViewCell *cell=[tableView dequeueReusableCellWithIdentifier:reuse];if(!cell)cell=[[UITableViewCell alloc] initWithStyle:sourceURL?UITableViewCellStyleSubtitle:UITableViewCellStyleValue1 reuseIdentifier:reuse];cell.backgroundColor=HostCard();cell.textLabel.text=row[@"title"];cell.textLabel.textColor=HostText();cell.textLabel.numberOfLines=0;cell.textLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];cell.textLabel.adjustsFontForContentSizeCategory=YES;cell.detailTextLabel.text=row[@"value"];cell.detailTextLabel.textColor=HostSecondaryText();cell.detailTextLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];cell.detailTextLabel.adjustsFontForContentSizeCategory=YES;cell.detailTextLabel.numberOfLines=0;cell.detailTextLabel.textAlignment=sourceURL?NSTextAlignmentLeft:NSTextAlignmentNatural;cell.accessoryType=row[@"action"]?UITableViewCellAccessoryDisclosureIndicator:UITableViewCellAccessoryNone;cell.selectionStyle=row[@"action"]?UITableViewCellSelectionStyleDefault:UITableViewCellSelectionStyleNone;return cell;}
- (void)probeInterface {if(!self.running){self.probeStatus=@"服务未运行 · 未检测";[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];return;}NSString *path=[self.service[@"playlistPath"] isKindOfClass:NSString.class]?self.service[@"playlistPath"]:@"";self.probingPlaylist=path.length>0;if(!self.probingPlaylist&&self.mediaCapable)path=@"/api/v1/capabilities";if(!path.length){self.probeStatus=@"未声明列表路径 · 编辑填写";[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];return;}NSInteger port=[self.service[@"port"] integerValue];NSString *trimmed=[path stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(port<1||port>65535||![trimmed isEqualToString:path]||![path hasPrefix:@"/"]||[path hasPrefix:@"//"]||[path containsString:@".."]||[path containsString:@"?"]||[path containsString:@"#"]||[path containsString:@"\\"]||[path containsString:@":"]||[path rangeOfCharacterFromSet:NSCharacterSet.controlCharacterSet].location!=NSNotFound){self.probeStatus=@"接口地址配置无效 · 请检查端口和列表路径";[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];return;}self.probeGeneration++;[self.probeTask cancel];[self.probeSession invalidateAndCancel];NSURLSessionConfiguration *config=NSURLSessionConfiguration.ephemeralSessionConfiguration;config.timeoutIntervalForRequest=5;config.timeoutIntervalForResource=7;config.URLCache=nil;self.probeSession=[NSURLSession sessionWithConfiguration:config delegate:self delegateQueue:nil];NSString *url=[NSString stringWithFormat:@"%@%@",self.baseURL,path];NSMutableURLRequest *request=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];request.HTTPMethod=@"GET";self.probeData=[NSMutableData data];self.probeStatusCode=0;self.probeChannelCount=0;self.probePlaylistChecked=NO;self.probeStatus=@"正在检测本机接口…";[self.tableView reloadSections:[NSIndexSet indexSetWithIndexesInRange:NSMakeRange(1,2)] withRowAnimation:UITableViewRowAnimationNone];self.probeTask=[self.probeSession dataTaskWithRequest:request];[self.probeTask resume];}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)ip {[tableView deselectRowAtIndexPath:ip animated:YES];NSDictionary *row=[self rowAt:ip];NSString *action=row[@"action"];if(ip.section==0 && [row[@"title"] isEqual:@"打开影视"]){if(self.onUse)self.onUse(self.service,@"vod");return;}if(ip.section==0 && [row[@"title"] isEqual:@"打开直播频道"]){if(self.onUse)self.onUse(self.service,@"live");return;}if([action isEqual:@"configuration"]){if(self.onUse)self.onUse(self.service,@"configuration");return;}if([action isEqual:@"update"]){if(self.onUpdate)self.onUpdate(self.service);return;}if([action isEqual:@"rollback"]){UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"切回上一版代码？" message:@"会先停止此服务，再切换到保留的上一版代码。账号、日志和当前端口会保留。" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"切换" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){if(self.onRollback)self.onRollback(self.service);}]];[self presentViewController:alert animated:YES completion:nil];return;}if([action isEqual:@"toggle"]){if(self.operationPending)return;if(!self.onToggle){[self showError:@"服务控制暂不可用"];return;}self.operationPending=YES;[self.tableView reloadSections:[NSIndexSet indexSetWithIndex:1] withRowAnimation:UITableViewRowAnimationNone];__weak typeof(self) weakSelf=self;self.onToggle(self.service,!self.running,^(NSError *error){dispatch_async(dispatch_get_main_queue(),^{PluginResourceDetailViewController *owner=weakSelf;if(!owner)return;owner.operationPending=NO;if(error)[owner showError:error.localizedDescription?:@"服务操作失败，请查看此资源日志"];[owner.tableView reloadData];});});return;}if([action isEqual:@"probe"]){[self probeInterface];return;}if([action isEqual:@"copy"]||[action isEqual:@"copySource"]){UIPasteboard.generalPasteboard.string=row[@"value"];[self showNotice:[action isEqual:@"copySource"]?@"资源来源地址已复制（包含原查询参数）":@"本机服务地址已复制"];return;}if([action isEqual:@"log"]){if(self.onLog)self.onLog(self.service);return;}if([action isEqual:@"remove"]){UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"移除此资源？" message:@"会移除本机服务代码及配置。" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"移除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){if(self.onRemove)self.onRemove(self.service);}]];[self presentViewController:alert animated:YES completion:nil];}}
- (void)showNotice:(NSString *)message {if(!message.length)return;self.navigationItem.prompt=message;dispatch_after(dispatch_time(DISPATCH_TIME_NOW,2*NSEC_PER_SEC),dispatch_get_main_queue(),^{if([self.navigationItem.prompt isEqual:message])self.navigationItem.prompt=nil;});}
- (void)showError:(NSString *)message {if(!message.length)return;UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"服务操作失败" message:message preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"查看日志" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){if(self.onLog)self.onLog(self.service);}]];[alert addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:alert animated:YES completion:nil];}
@end
